47	void interrupt_helper(regs_context_t *regs, uint64_t stval, uint64_t cause)
48	{
49	    // call corresponding handler by the value of `cause`
50	    cpu_id = get_current_cpu_id();
51	    current_cpu_running = current_running[cpu_id];
52	    if(cause & SCAUSE_IRQ_FLAG){
53	        cause = cause & ~SCAUSE_IRQ_FLAG;
54	        (*irq_table[cause])(regs, stval, cause);
55	    }
56	    else{
57	        (*exc_table[cause])(regs, stval, cause);
58	    }
59	}
