878	static void XEmacPsSendHandler(void *Callback)
879	{
880	    // TODO: you finish sending packet now
881	    XEmacPs *EmacPsInstancePtr = (XEmacPs *)Callback;
882	    /*
883	     * Disable the transmit related interrupts
884	     */
885	    /*XEmacPs_IntDisable(
886	        EmacPsInstancePtr,
887	        (XEMACPS_IXR_TXCOMPL_MASK | XEMACPS_IXR_TX_ERR_MASK));*/
888	
889	    /*
890	     * Increment the counter so that main thread knows something
891	     * happened.
892	     */
893	    do_unblock(net_send_queue.next);
894	    u32 Reg = XEmacPs_ReadReg(EmacPsInstancePtr->Config.BaseAddress, XEMACPS_ISR_OFFSET);
895	    Reg = Reg | XEMACPS_IXR_TXCOMPL_MASK;
896		XEmacPs_WriteReg(EmacPsInstancePtr->Config.BaseAddress, XEMACPS_ISR_OFFSET, Reg);
897	    send_transaction = 0;
