```c
long do_net_recv(uintptr_t addr, size_t length, int num_packet, size_t* frLength)
{
    // record parameters for the irq handler
    _addr = addr;
    _num_packet = num_packet;
    _frLength = frLength;
    recv_transaction = 1;

    // start receiving: program RX BDs to receive num_packet frames
    EmacPsRecv(&EmacPsInstance, rx_buffers, num_packet);

    if (net_poll_mode) {
        // poll mode: busy wait until all packets received
        EmacPsWaitRecv(&EmacPsInstance, num_packet, rx_len);
        uintptr_t rx_curr = addr;
        for (int i = 0; i < num_packet; i++) {
            memcpy((uint8_t *)rx_curr, (uint8_t *)&rx_buffers[i], rx_len[i]);
            *(frLength + i) = rx_len[i];
            rx_curr += rx_len[i];
        }
        recv_transaction = 0;
    } else {
        // irq mode: block until the receive interrupt handler wakes us
        do_block(&current_running[get_current_cpu_id()]->list, &net_recv_queue);
        scheduler();
    }
    return 0;
}
```

